import { describe, expect, it } from 'vitest';
import { parseResearchDocument } from './report';

// The built-in research files shipped in public/research/ (generated by bench/publish_demo.py).
const files = import.meta.glob('../../public/research/*', { query: '?raw', import: 'default', eager: true }) as Record<string, string>;
const read = (id: string) => files[`../../public/research/${id}`];
const indexText = read('index.json');

describe.skipIf(!indexText)('built-in research files', () => {
  const items = (indexText ? JSON.parse(indexText).items : []) as { id: string; kind: string; title: string; file: string }[];

  it('lists at least the headline result and a trace, all present', () => {
    expect(items.some((i) => i.kind === 'report')).toBe(true);
    expect(items.some((i) => i.kind === 'trace')).toBe(true);
    for (const i of items) {
      expect(i.file).toBe(`/research/${i.id}`);
      expect(read(i.id)).toBeTruthy();
    }
  });

  it.each(items.filter((i) => i.kind === 'report').map((i) => [i.title, i.id]))('parses report: %s', (_title, id) => {
    expect(() => parseResearchDocument(read(id))).not.toThrow();
  });

  it.each(items.filter((i) => i.kind === 'trace').map((i) => [i.title, i.id]))('trace frames are analysed: %s', (_title, id) => {
    const lines = read(id).trim().split('\n');
    expect(JSON.parse(lines[0]).type).toBe('header');
    expect(lines.slice(1).every((l: string) => 'summary' in JSON.parse(l))).toBe(true);
  });
});
